const messages = {
  nl: {
    enquiry:{number:'01',title:'Een goede eerste indruk',text:'Bedankt voor je aanvraag over [project]. Ik bekijk je vraag en laat je uiterlijk [datum] weten wat ik voor je kan doen.'},
    quote:{number:'07',title:'Even vriendelijk opvolgen',text:'Is de offerte voor [project] goed aangekomen? Ik stuur hem graag opnieuw als de bijlage ontbreekt.'},
    review:{number:'18',title:'Ruimte voor een mooie review',text:'Wil je je ervaring met [dienst] delen? Via [reviewlink] kun je in je eigen woorden vertellen hoe de samenwerking verliep. Alvast bedankt voor je tijd.'}
  },
  en: {
    enquiry:{number:'01',title:'A good first impression',text:'Thanks for asking about [project]. I’ll review your request and get back to you by [date] with a next step.'},
    quote:{number:'07',title:'A friendly follow-up',text:'Did the quote for [project] reach you? I’m happy to resend it if the attachment is missing.'},
    review:{number:'18',title:'Make room for a lovely review',text:'Would you like to share your experience of [service]? You can describe how the project went in your own words at [review link]. Thank you for your time.'}
  }
};
let language = 'nl';
let currentMessage = 'enquiry';
const $ = selector => document.querySelector(selector);
function renderMessage(){
  const message = messages[language][currentMessage];
  $('#message-title').textContent = message.title;
  $('#message-number').textContent = `${language === 'nl' ? 'BERICHT' : 'MESSAGE'} ${message.number}`;
  const content = $('#message-text');
  content.replaceChildren();
  for (const segment of message.text.split(/(\[[^\]]+\])/g)) {
    if (segment.startsWith('[')) {
      const span = document.createElement('span');
      span.className = 'placeholder';
      span.textContent = segment;
      content.append(span);
    } else content.append(document.createTextNode(segment));
  }
  $('#copy-status').textContent = '';
}
function setLanguage(nextLanguage){
  if (!translations[nextLanguage]) return;
  language = nextLanguage;
  document.documentElement.lang = language;
  document.title = language === 'nl' ? 'SlimStart Studio · De Klantstart Toolkit' : 'SlimStart Studio · The Client Onboarding Toolkit';
  document.querySelectorAll('[data-i18n]').forEach(element => {
    const text = translations[language][element.dataset.i18n];
    if (text === undefined) return;
    element.replaceChildren();
    text.split('\n').forEach((line, index) => {
      if (index) element.append(document.createElement('br'));
      element.append(document.createTextNode(line));
    });
  });
  document.querySelectorAll('[data-lang]').forEach(button => button.setAttribute('aria-pressed',String(button.dataset.lang === language)));
  $('[data-nav-label]').setAttribute('aria-label',language === 'nl' ? 'Hoofdnavigatie' : 'Main navigation');
  $('[data-tabs-label]').setAttribute('aria-label',language === 'nl' ? 'Berichtvoorbeelden' : 'Sample messages');
  $('[data-art-label]').setAttribute('aria-label',language === 'nl' ? 'Illustratie van de Klantstart Toolkit: een groene handleiding, klantbericht en Excel-overzicht' : 'Illustration of the Client Onboarding Toolkit: a green guide, client message and Excel overview');
  $('#close-dialog').setAttribute('aria-label',language === 'nl' ? 'Sluiten' : 'Close');
  const description = language === 'nl' ? 'Van eerste aanvraag tot review: de Klantstart Toolkit van SlimStart Studio. Twintig klantberichten per taal, PDF-handleidingen en een Excel-klantenbestand. Nederlands en Engels.' : 'From first enquiry to final review: the Client Onboarding Toolkit by SlimStart Studio. Twenty messages in each language, PDF guides and an Excel tracker. Dutch and English.';
  $('meta[name="description"]').setAttribute('content',description);
  $('meta[property="og:title"]').setAttribute('content',document.title);
  $('meta[property="og:description"]').setAttribute('content',description);
  renderMessage();
  try { localStorage.setItem('slimstart-language',language); } catch (_) { /* Language switching also works without storage. */ }
}
document.querySelectorAll('[data-lang]').forEach(button => button.addEventListener('click',() => setLanguage(button.dataset.lang)));
function selectMessage(button){
  currentMessage = button.dataset.message;
  document.querySelectorAll('[data-message]').forEach(tab => {
    const selected = tab === button;
    tab.setAttribute('aria-selected',String(selected));
    tab.tabIndex = selected ? 0 : -1;
  });
  $('#message-panel').setAttribute('aria-labelledby',button.id);
  renderMessage();
}
const messageTabs = [...document.querySelectorAll('[data-message]')];
messageTabs.forEach((button,index) => {
  button.addEventListener('click',() => selectMessage(button));
  button.addEventListener('keydown',event => {
    let nextIndex;
    if(event.key === 'ArrowRight') nextIndex = (index+1)%messageTabs.length;
    else if(event.key === 'ArrowLeft') nextIndex = (index-1+messageTabs.length)%messageTabs.length;
    else if(event.key === 'Home') nextIndex = 0;
    else if(event.key === 'End') nextIndex = messageTabs.length-1;
    else return;
    event.preventDefault();
    messageTabs[nextIndex].focus();
    selectMessage(messageTabs[nextIndex]);
  });
});
$('#copy-message').addEventListener('click',async () => {
  const text = messages[language][currentMessage].text;
  try {
    if (!navigator.clipboard?.writeText) throw new Error('Clipboard unavailable');
    await navigator.clipboard.writeText(text);
    $('#copy-status').textContent = translations[language].copied;
  } catch (_) {
    const range = document.createRange();
    range.selectNodeContents($('#message-text'));
    const selection = window.getSelection();
    selection.removeAllRanges();
    selection.addRange(range);
    $('#copy-status').textContent = translations[language].copyFailed;
  }
});
const dialog = $('#availability-dialog');
$('#availability-button').addEventListener('click',() => dialog.showModal());
$('#close-dialog').addEventListener('click',() => dialog.close());
dialog.addEventListener('click',event => {
  if (event.target !== dialog) return;
  const rect = dialog.getBoundingClientRect();
  if(event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) dialog.close();
});
$('#dialog-preview').addEventListener('click',() => {
  dialog.close();
  $('#voorbeeld').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
  messageTabs.find(tab => tab.getAttribute('aria-selected') === 'true').focus({preventScroll:true});
});
$('#year').textContent = new Date().getFullYear();
try { const saved = localStorage.getItem('slimstart-language'); if (saved && translations[saved]) language = saved; } catch (_) { /* Storage is optional. */ }
setLanguage(language);
